const { validateSyncConfig } = require('./validation');
const {
  createUnsupportedObjectResult,
  getObjectExecutor,
  isUnsupportedObjectType
} = require('./object-registry');
const { SYNC_DEPENDENCIES } = require('./dependencies');
const { requireWithFallback } = require('./require-package');

const { createStoreClient } = requireWithFallback(
  require,
  '@synclistic/shopify-client',
  '../../shopify-client'
);

const noopReporter = {
  info() {},
  warn() {},
  error() {},
  objectStarted() {},
  objectFinished() {}
};

function toObjectResult(objectType, result) {
  return {
    objectType,
    status: result.status || 'success',
    created: result.created || 0,
    updated: result.updated || 0,
    deleted: result.deleted || 0,
    warnings: result.warnings || [],
    errors: result.errors || [],
    summary: result.summary || {}
  };
}

function buildRunSummary(objectResults) {
  const counts = {
    successfulObjects: 0,
    failedObjects: 0,
    skippedObjects: 0
  };

  for (const result of objectResults) {
    if (result.status === 'failed') {
      counts.failedObjects += 1;
    } else if (result.status === 'skipped') {
      counts.skippedObjects += 1;
    } else {
      counts.successfulObjects += 1;
    }
  }

  return counts;
}

function toErrorMessage(error, fallbackMessage) {
  if (!error) {
    return fallbackMessage;
  }

  if (typeof error === 'string') {
    return error;
  }

  return error.message || fallbackMessage;
}

async function runSync(config, deps = {}) {
  const validation = validateSyncConfig(config);
  if (!validation.valid) {
    return {
      success: false,
      config: null,
      orderedObjects: [],
      objectResults: [],
      warnings: [],
      errors: validation.errors.map((error) => error.message),
      validationErrors: validation.errors
    };
  }

  const normalizedConfig = validation.normalizedConfig;
  const reporter = deps.reporter || noopReporter;
  const executeObject = deps.executeObject;
  const exportBeforeSync = deps.exportBeforeSync;
  const resolveObjectExecutor = deps.getObjectExecutor || getObjectExecutor;
  const clientFactory = deps.clientFactory || createStoreClient;
  const warnings = [];
  const errors = [];
  const objectResults = [];
  const client =
    clientFactory && normalizedConfig.source && normalizedConfig.destination
      ? {
          source: clientFactory(normalizedConfig.source),
          destination: clientFactory(normalizedConfig.destination)
        }
      : null;

  reporter.info('Sync run started', {
    source: normalizedConfig.source,
    destination: normalizedConfig.destination
  });

  if (normalizedConfig.exportBeforeSync && exportBeforeSync) {
    try {
      await exportBeforeSync({ config: normalizedConfig, reporter });
    } catch (error) {
      const message = toErrorMessage(error, 'Export before sync failed');
      errors.push(message);
      reporter.error('Export before sync failed', {
        error: message,
        details: error && error.result ? error.result : null
      });

      reporter.info('Sync run finished', {
        success: false,
        successfulObjects: 0,
        failedObjects: 0,
        skippedObjects: 0
      });

      return {
        success: false,
        config: normalizedConfig,
        orderedObjects: normalizedConfig.orderedObjects,
        objectResults,
        warnings,
        errors,
        validationErrors: []
      };
    }
  }

  for (const objectType of normalizedConfig.orderedObjects) {
    reporter.objectStarted(objectType, { syncMode: normalizedConfig.syncMode });

    let result;
    try {
      const failedDependencies = (SYNC_DEPENDENCIES[objectType] || []).filter((dependency) =>
        objectResults.some(
          (entry) => entry.objectType === dependency && entry.status === 'failed'
        )
      );

      if (failedDependencies.length > 0) {
        result = {
          status: 'skipped',
          warnings: [
            `${objectType} sync skipped because required dependencies failed: ${failedDependencies.join(', ')}`
          ],
          summary: {
            dependencyFailure: true,
            failedDependencies
          }
        };
      }

      if ((result === null || typeof result === 'undefined') && executeObject) {
        result = await executeObject(objectType, {
          config: normalizedConfig,
          reporter,
          client
        });
      }

      if (result === null || typeof result === 'undefined') {
        const handler = resolveObjectExecutor(objectType);

        if (handler) {
          result = await handler({
            config: normalizedConfig,
            reporter,
            client
          });
        }
      }
    } catch (error) {
      result = {
        status: 'failed',
        errors: [toErrorMessage(error, `Sync failed for ${objectType}`)]
      };
    }

    if (result === null || typeof result === 'undefined') {
      result = isUnsupportedObjectType(objectType)
        ? createUnsupportedObjectResult(objectType)
        : {
            status: 'skipped',
            warnings: [`No executor registered for ${objectType}`],
            summary: {}
          };
    }

    const objectResult = toObjectResult(objectType, result || {});
    objectResults.push(objectResult);
    warnings.push(...objectResult.warnings);
    errors.push(...objectResult.errors);

    reporter.objectFinished(objectType, {
      status: objectResult.status,
      created: objectResult.created,
      updated: objectResult.updated,
      deleted: objectResult.deleted,
      warnings: objectResult.warnings,
      errors: objectResult.errors,
      summary: objectResult.summary
    });
  }

  const summary = buildRunSummary(objectResults);
  const success = summary.failedObjects === 0 && errors.length === 0;

  reporter.info('Sync run finished', {
    success,
    ...summary
  });

  return {
    success,
    config: normalizedConfig,
    orderedObjects: normalizedConfig.orderedObjects,
    objectResults,
    warnings,
    errors,
    validationErrors: []
  };
}

module.exports = {
  runSync
};
